def is_simple_power(x, n):
    """
    Return True if x is a simple power of n, i.e. x == n**k
    for some non-negative integer k.
    """
    if x == 1:
        return True

    if n == 1:
        return False
    if n == -1:
        return x == -1
    if n == 0:
        return x == 0

    power = 1
    while abs(power) < abs(x):
        power *= n

    return power == x
